-- 50 Jellyfish Bloom: swims the jellyfish and sways the kelp. Every
-- tentacle, arm and stalk is a chain of `jiggle` bones, so this only moves
-- each jellyfish's root (and turns each stalk's foot): the trailing, the
-- streaming after a pulse and the whip of a turn are the engine's.
-- Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/50-jellyfish-bloom.scene"
local JELLIES = 5
local KELP = 7
local TOP, BOTTOM = 720, -470
local captions = true
local strong = false
local jellies, kelp = {}, {}
local status
local t = 0
local lead = 0
local last_mx, last_my

function init(entity)
    for i = 1, JELLIES do
        local root = Entity.find_by_name("Jelly" .. i)
        local x, y = Transform.get_position(root)
        local s = Transform.get_scale(root)
        jellies[i] = { root = root, bell = Entity.find_by_name("Jelly" .. i .. "Bell"), x = x, y = y, home = x,
                       scale = s, phase = (i * 0.37) % 1, period = 2.0 + 0.35 * i, boost = 0, vx = 0 }
    end
    for i = 1, KELP do kelp[i] = Entity.find_by_name("Kelp" .. i .. "_1") end
    status = Entity.find_by_name("Status")
end

local function clamp(v, lo, hi) return math.max(lo, math.min(hi, v)) end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("C") then strong = not strong end
    local startle = Input.is_key_just_pressed("Space")
    t = t + dt

    -- The mouse leads the nearest jellyfish once it moves, for a while.
    local mx, my = Input.get_mouse_world_position()
    if last_mx and (math.abs(mx - last_mx) + math.abs(my - last_my)) > 1 then lead = 3 end
    last_mx, last_my = mx, my
    lead = math.max(0, lead - dt)

    local current = strong and 1 or 0.3
    for i, j in ipairs(jellies) do
        if startle then j.phase, j.boost = 0, 1.2 end
        j.phase = j.phase + dt / j.period
        if j.phase >= 1 then j.phase = j.phase - 1 end
        j.boost = math.max(0, j.boost - dt)
        local p = j.phase
        -- A pulse: the bell squeezes, then the jellyfish coasts upward.
        local squeeze = p < 0.22 and math.sin(p / 0.22 * math.pi) or 0
        local up = (10 + 80 * math.exp(-p * 4)) * j.scale * (1 + 1.5 * j.boost)
        local x0 = j.x
        if i == 1 and lead > 0 then
            j.x = j.x + (mx - j.x) * math.min(1, dt * 1.6)
            j.y = j.y + (my - j.y) * math.min(1, dt * 1.6)
        else
            j.y = j.y + up * dt
            local drift = j.home + (60 + 140 * current) * math.sin(t * (0.12 + 0.03 * i) + i * 1.9)
            j.x = j.x + (drift - j.x) * math.min(1, dt * 0.8)
            if j.y > TOP then
                j.y = BOTTOM
                j.x = j.home
            end
        end
        j.vx = j.vx + ((j.x - x0) / math.max(dt, 1e-4) - j.vx) * math.min(1, dt * 4)
        Transform.set_position(j.root, j.x, j.y)
        -- Leaning into the way it drifts: a turn the tentacles whip after.
        Transform.set_rotation(j.root, clamp(-j.vx * 0.004, -0.5, 0.5))
        if j.bell then Transform.set_scale(j.bell, 1 - 0.18 * squeeze, 1 + 0.08 * squeeze) end
    end

    -- Kelp: the foot of each stalk rocks in the current; the stalk follows.
    for i, k in ipairs(kelp) do
        local sway = (0.06 + 0.22 * current) * math.sin(t * (0.5 + 0.07 * i) + i * 1.3)
        Transform.set_rotation(k, 1.5708 + sway)
    end
    if status then UI.set_text(status, "current: " .. (strong and "strong" or "calm")) end
end
